[System.IO.Directory]::SetCurrentDirectory($PWD.Path)

$files = @{
    "app\sentinel\lib\config.ts" = ""
    "app\sentinel\layout.tsx" = ""
    "app\sentinel\new-project\page.tsx" = ""
}
foreach ($path in $files.Keys) {
    $bytes = [System.Convert]::FromBase64String($files[$path])
    New-Item -ItemType Directory -Force -Path (Split-Path $path) | Out-Null
    [System.IO.File]::WriteAllBytes($path, $bytes)
    Write-Host "wrote $path ($($bytes.Length) bytes)"
}
Write-Host "`nDone -- 3 files written."
